CREATE TABLE public.pr_home_monthly_summary (id integer PRIMARY KEY CHECK(id=1),month_start date NOT NULL,km numeric,outings bigint,participants bigint,weekly jsonb NOT NULL DEFAULT '[]'::jsonb,updated_at timestamptz NOT NULL);
ALTER TABLE public.pr_home_monthly_summary ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.pr_home_monthly_summary FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.pr_home_monthly_summary TO anon,authenticated;
CREATE POLICY pr_home_read_aggregate ON public.pr_home_monthly_summary FOR SELECT TO anon,authenticated USING (id=1);
WITH bounds AS (SELECT date_trunc('month',now() AT TIME ZONE 'America/Montevideo')::date AS month_start, (now() AT TIME ZONE 'America/Montevideo')::date AS today),
rides AS (SELECT alumno_id, distancia_metros, floor((extract(day from fecha_inicio AT TIME ZONE 'America/Montevideo')-1)/7)::int+1 AS bucket FROM public.pr_inline_skate_public_activities CROSS JOIN bounds WHERE fecha_inicio >= (month_start::timestamp AT TIME ZONE 'America/Montevideo') AND fecha_inicio <= now() AND visible_feed IS TRUE AND es_privada IS FALSE AND eliminada IS FALSE AND fuente='strava' AND distancia_metros>0 AND alumno_id IS NOT NULL),
totals AS (SELECT count(DISTINCT alumno_id) AS participants,count(*) AS outings,coalesce(round(sum(distancia_metros)/1000,1),0) AS km FROM rides),
buckets AS (SELECT n AS bucket, count(DISTINCT r.alumno_id) AS participants,count(r.alumno_id) AS outings,coalesce(round(sum(r.distancia_metros)/1000,1),0) AS km FROM bounds CROSS JOIN LATERAL generate_series(1,((extract(day from today)::int-1)/7)+1) n LEFT JOIN rides r ON r.bucket=n GROUP BY n),
chart AS (SELECT CASE WHEN bool_and(participants>=3 OR outings=0) THEN jsonb_agg(jsonb_build_object('bucket',bucket,'km',km) ORDER BY bucket) ELSE '[]'::jsonb END AS weekly FROM buckets)
INSERT INTO public.pr_home_monthly_summary(id,month_start,km,outings,participants,weekly,updated_at) SELECT 1,month_start,CASE WHEN participants>=3 THEN km END,CASE WHEN participants>=3 THEN outings END,CASE WHEN participants>=3 THEN participants END,CASE WHEN participants>=3 THEN weekly ELSE '[]'::jsonb END,now() FROM bounds CROSS JOIN totals CROSS JOIN chart ON CONFLICT(id) DO UPDATE SET month_start=excluded.month_start,km=excluded.km,outings=excluded.outings,participants=excluded.participants,weekly=excluded.weekly,updated_at=excluded.updated_at;
SELECT cron.schedule('pr-home-monthly-summary','*/30 * * * *',$pr_home$WITH bounds AS (SELECT date_trunc('month',now() AT TIME ZONE 'America/Montevideo')::date AS month_start, (now() AT TIME ZONE 'America/Montevideo')::date AS today),
rides AS (SELECT alumno_id, distancia_metros, floor((extract(day from fecha_inicio AT TIME ZONE 'America/Montevideo')-1)/7)::int+1 AS bucket FROM public.pr_inline_skate_public_activities CROSS JOIN bounds WHERE fecha_inicio >= (month_start::timestamp AT TIME ZONE 'America/Montevideo') AND fecha_inicio <= now() AND visible_feed IS TRUE AND es_privada IS FALSE AND eliminada IS FALSE AND fuente='strava' AND distancia_metros>0 AND alumno_id IS NOT NULL),
totals AS (SELECT count(DISTINCT alumno_id) AS participants,count(*) AS outings,coalesce(round(sum(distancia_metros)/1000,1),0) AS km FROM rides),
buckets AS (SELECT n AS bucket, count(DISTINCT r.alumno_id) AS participants,count(r.alumno_id) AS outings,coalesce(round(sum(r.distancia_metros)/1000,1),0) AS km FROM bounds CROSS JOIN LATERAL generate_series(1,((extract(day from today)::int-1)/7)+1) n LEFT JOIN rides r ON r.bucket=n GROUP BY n),
chart AS (SELECT CASE WHEN bool_and(participants>=3 OR outings=0) THEN jsonb_agg(jsonb_build_object('bucket',bucket,'km',km) ORDER BY bucket) ELSE '[]'::jsonb END AS weekly FROM buckets)
INSERT INTO public.pr_home_monthly_summary(id,month_start,km,outings,participants,weekly,updated_at) SELECT 1,month_start,CASE WHEN participants>=3 THEN km END,CASE WHEN participants>=3 THEN outings END,CASE WHEN participants>=3 THEN participants END,CASE WHEN participants>=3 THEN weekly ELSE '[]'::jsonb END,now() FROM bounds CROSS JOIN totals CROSS JOIN chart ON CONFLICT(id) DO UPDATE SET month_start=excluded.month_start,km=excluded.km,outings=excluded.outings,participants=excluded.participants,weekly=excluded.weekly,updated_at=excluded.updated_at;$pr_home$);
